package com.example.keyvaultconfig;

import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

import java.time.Clock;
import java.time.Duration;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;

public final class AsyncSecretCache {
    private final AsyncSecretProvider provider;
    private final Map<String, String> defaults;
    private final Duration warningWindow;
    private final Clock clock;
    private final Map<String, SecretValue> cache = new ConcurrentHashMap<>();

    public AsyncSecretCache(
            AsyncSecretProvider provider,
            Map<String, String> defaults,
            Duration warningWindow) {
        this(provider, defaults, warningWindow, Clock.systemUTC());
    }

    AsyncSecretCache(
            AsyncSecretProvider provider,
            Map<String, String> defaults,
            Duration warningWindow,
            Clock clock) {
        this.provider = Objects.requireNonNull(provider, "provider");
        this.defaults = Map.copyOf(defaults);
        this.warningWindow = requireNonNegative(warningWindow);
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    public Mono<Map<String, String>> loadRequired(Collection<String> names) {
        return Flux.fromIterable(names)
                .flatMap(this::refresh)
                .then(Mono.fromSupplier(this::snapshot));
    }

    public Mono<String> get(String name) {
        return Mono.defer(() -> {
            SecretValue current = cache.get(name);
            if (current == null || current.expiresWithin(warningWindow, clock)) {
                return refresh(name).map(SecretValue::value);
            }
            return Mono.just(current.value());
        });
    }

    public Mono<SecretValue> refresh(String name) {
        return provider.getSecret(name, defaultFor(name))
                .doOnNext(secret -> cache.put(name, secret));
    }

    public Mono<List<SecretValue>> secretsNearExpiry() {
        return Mono.fromSupplier(() -> cache.values().stream()
                .filter(SecretValue::found)
                .filter(secret -> secret.expiresWithin(warningWindow, clock))
                .toList());
    }

    public Map<String, String> snapshot() {
        Map<String, String> values = new ConcurrentHashMap<>();
        cache.forEach((name, secret) -> values.put(name, secret.value()));
        return Map.copyOf(values);
    }

    private String defaultFor(String name) {
        Objects.requireNonNull(name, "name");
        return defaults.getOrDefault(name, "");
    }

    private static Duration requireNonNegative(Duration duration) {
        Objects.requireNonNull(duration, "warningWindow");
        if (duration.isNegative()) {
            throw new IllegalArgumentException("warningWindow must not be negative");
        }
        return duration;
    }
}

package com.example.keyvaultconfig;

import com.azure.core.exception.ResourceNotFoundException;
import com.azure.security.keyvault.secrets.SecretAsyncClient;
import com.azure.security.keyvault.secrets.models.KeyVaultSecret;
import reactor.core.publisher.Mono;

import java.util.Objects;

public final class AsyncSecretProvider {
    private final SecretAsyncClient client;

    public AsyncSecretProvider(SecretAsyncClient client) {
        this.client = Objects.requireNonNull(client, "client");
    }

    public Mono<SecretValue> getSecret(String name, String defaultValue) {
        return getSecret(name, null, defaultValue);
    }

    public Mono<SecretValue> getSecret(String name, String version, String defaultValue) {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(defaultValue, "defaultValue");
        Mono<KeyVaultSecret> request = version == null
                ? client.getSecret(name)
                : client.getSecret(name, version);
        return request
                .map(AsyncSecretProvider::toSecretValue)
                .onErrorResume(
                        ResourceNotFoundException.class,
                        exception -> Mono.just(SecretValue.missing(name, defaultValue)));
    }

    private static SecretValue toSecretValue(KeyVaultSecret secret) {
        return new SecretValue(
                secret.getName(),
                secret.getValue(),
                secret.getProperties().getVersion(),
                secret.getProperties().getExpiresOn(),
                true);
    }
}

package com.example.keyvaultconfig;

import com.azure.core.exception.ResourceNotFoundException;
import com.azure.security.keyvault.secrets.SecretAsyncClient;
import com.azure.security.keyvault.secrets.models.KeyVaultSecret;
import com.azure.security.keyvault.secrets.models.SecretProperties;
import reactor.core.publisher.Mono;

import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.Objects;
import java.util.concurrent.TimeoutException;

public final class AsyncSecretRotationHelper {
    private final SecretAsyncClient client;
    private final Duration purgeTimeout;
    private final Duration pollInterval;

    public AsyncSecretRotationHelper(SecretAsyncClient client) {
        this(client, Duration.ofMinutes(2), Duration.ofSeconds(2));
    }

    public AsyncSecretRotationHelper(
            SecretAsyncClient client,
            Duration purgeTimeout,
            Duration pollInterval) {
        this.client = Objects.requireNonNull(client, "client");
        this.purgeTimeout = requirePositive(purgeTimeout, "purgeTimeout");
        this.pollInterval = requirePositive(pollInterval, "pollInterval");
    }

    public Mono<KeyVaultSecret> rotate(
            String name,
            String newValue,
            OffsetDateTime expiresOn) {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(newValue, "newValue");
        Objects.requireNonNull(expiresOn, "expiresOn");

        return client.beginDeleteSecret(name)
                .last()
                .then(client.purgeDeletedSecret(name))
                .then(Mono.defer(() ->
                        waitUntilPurged(name, Instant.now().plus(purgeTimeout))))
                .then(client.setSecret(new KeyVaultSecret(name, newValue)
                        .setProperties(new SecretProperties().setExpiresOn(expiresOn))));
    }

    private Mono<Void> waitUntilPurged(String name, Instant deadline) {
        return client.getDeletedSecret(name)
                .flatMap(ignored -> {
                    if (Instant.now().isAfter(deadline)) {
                        return Mono.<Void>error(new TimeoutException(
                                "Timed out waiting for secret '" + name + "' to be fully purged"));
                    }
                    return Mono.delay(pollInterval).then(waitUntilPurged(name, deadline));
                })
                .onErrorResume(ResourceNotFoundException.class, exception -> Mono.empty());
    }

    private static Duration requirePositive(Duration duration, String name) {
        Objects.requireNonNull(duration, name);
        if (duration.isZero() || duration.isNegative()) {
            throw new IllegalArgumentException(name + " must be positive");
        }
        return duration;
    }
}

package com.example.keyvaultconfig;

import com.azure.core.credential.TokenCredential;
import com.azure.identity.ManagedIdentityCredentialBuilder;
import com.azure.security.keyvault.secrets.SecretAsyncClient;
import com.azure.security.keyvault.secrets.SecretClient;
import com.azure.security.keyvault.secrets.SecretClientBuilder;

import java.net.URI;
import java.util.Map;
import java.util.Objects;

public final class KeyVaultClientFactory {
    public static final String VAULT_URL_ENV = "AZURE_KEYVAULT_URL";
    public static final String MANAGED_IDENTITY_CLIENT_ID_ENV = "AZURE_CLIENT_ID";

    private KeyVaultClientFactory() {
    }

    public static Clients fromEnvironment() {
        return fromEnvironment(System.getenv());
    }

    static Clients fromEnvironment(Map<String, String> environment) {
        String vaultUrl = requireVaultUrl(environment.get(VAULT_URL_ENV));
        ManagedIdentityCredentialBuilder credentialBuilder = new ManagedIdentityCredentialBuilder();
        String clientId = environment.get(MANAGED_IDENTITY_CLIENT_ID_ENV);
        if (clientId != null && !clientId.isBlank()) {
            credentialBuilder.clientId(clientId);
        }
        TokenCredential credential = credentialBuilder.build();
        SecretClientBuilder clientBuilder = new SecretClientBuilder()
                .vaultUrl(vaultUrl)
                .credential(credential);
        return new Clients(clientBuilder.buildClient(), clientBuilder.buildAsyncClient());
    }

    private static String requireVaultUrl(String value) {
        if (value == null || value.isBlank()) {
            throw new IllegalStateException(VAULT_URL_ENV + " must be set");
        }
        URI uri = URI.create(value);
        if (!"https".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null) {
            throw new IllegalArgumentException(VAULT_URL_ENV + " must be an absolute HTTPS URL");
        }
        return value;
    }

    public record Clients(SecretClient sync, SecretAsyncClient async) {
        public Clients {
            Objects.requireNonNull(sync, "sync");
            Objects.requireNonNull(async, "async");
        }
    }
}

package com.example.keyvaultconfig;

import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Map;
import java.util.UUID;

public final class Main {
    private static final List<String> REQUIRED_KEYS =
            List.of("database-url", "api-key", "feature-flag");
    private static final Map<String, String> DEFAULTS = Map.of(
            "database-url", "jdbc:h2:mem:fallback",
            "api-key", "not-configured",
            "feature-flag", "false");
    private static final Duration EXPIRY_WARNING_WINDOW = Duration.ofDays(7);
    private static final String ROTATION_SECRET = "rotating-demo-secret";

    private Main() {
    }

    public static void main(String[] args) {
        KeyVaultClientFactory.Clients clients = KeyVaultClientFactory.fromEnvironment();
        runSyncDemo(clients);
        runAsyncDemo(clients);
    }

    private static void runSyncDemo(KeyVaultClientFactory.Clients clients) {
        System.out.println("=== Synchronous provider ===");
        SyncSecretProvider provider = new SyncSecretProvider(clients.sync());
        SyncSecretCache cache =
                new SyncSecretCache(provider, DEFAULTS, EXPIRY_WARNING_WINDOW);

        cache.loadRequired(REQUIRED_KEYS);
        REQUIRED_KEYS.forEach(name ->
                System.out.printf("%s loaded from cache (%d characters)%n",
                        name, cache.get(name).length()));
        cache.refresh("api-key");
        printExpiryWarnings(cache.secretsNearExpiry());

        SyncSecretRotationHelper rotation = new SyncSecretRotationHelper(clients.sync());
        rotation.rotate(
                ROTATION_SECRET,
                "sync-" + UUID.randomUUID(),
                OffsetDateTime.now(ZoneOffset.UTC).plusDays(90));
        cache.refresh(ROTATION_SECRET);
        System.out.println("Synchronous rotation completed.");
    }

    private static void runAsyncDemo(KeyVaultClientFactory.Clients clients) {
        System.out.println("=== Asynchronous provider ===");
        AsyncSecretProvider provider = new AsyncSecretProvider(clients.async());
        AsyncSecretCache cache =
                new AsyncSecretCache(provider, DEFAULTS, EXPIRY_WARNING_WINDOW);

        cache.loadRequired(REQUIRED_KEYS)
                .thenMany(reactor.core.publisher.Flux.fromIterable(REQUIRED_KEYS))
                .concatMap(name -> cache.get(name)
                        .doOnNext(value -> System.out.printf(
                                "%s loaded from cache (%d characters)%n",
                                name,
                                value.length())))
                .then(cache.refresh("api-key"))
                .then(cache.secretsNearExpiry())
                .doOnNext(Main::printExpiryWarnings)
                .then(new AsyncSecretRotationHelper(clients.async()).rotate(
                        ROTATION_SECRET,
                        "async-" + UUID.randomUUID(),
                        OffsetDateTime.now(ZoneOffset.UTC).plusDays(90)))
                .then(cache.refresh(ROTATION_SECRET))
                .doOnSuccess(ignored -> System.out.println("Asynchronous rotation completed."))
                .block();
    }

    private static void printExpiryWarnings(List<SecretValue> secrets) {
        secrets.forEach(secret -> System.out.printf(
                "WARNING: %s version %s expires at %s%n",
                secret.name(),
                secret.version(),
                secret.expiresOn()));
    }
}

package com.example.keyvaultconfig;

import java.time.Clock;
import java.time.Duration;
import java.time.OffsetDateTime;
import java.util.Objects;

public record SecretValue(
        String name,
        String value,
        String version,
        OffsetDateTime expiresOn,
        boolean found) {

    public SecretValue {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(value, "value");
    }

    public static SecretValue missing(String name, String defaultValue) {
        return new SecretValue(name, defaultValue, null, null, false);
    }

    public boolean expiresWithin(Duration warningWindow, Clock clock) {
        Objects.requireNonNull(warningWindow, "warningWindow");
        Objects.requireNonNull(clock, "clock");
        if (warningWindow.isNegative()) {
            throw new IllegalArgumentException("warningWindow must not be negative");
        }
        return expiresOn != null
                && !expiresOn.isAfter(OffsetDateTime.now(clock).plus(warningWindow));
    }

    public boolean expiresWithin(Duration warningWindow) {
        return expiresWithin(warningWindow, Clock.systemUTC());
    }
}

